/*@@SAFELAB_LIB@@*/

// ---- Shared helpers (same block in every SafeLab workflow) ----
const rowsOf = (node) => $(node).all().map((i) => i.json).filter((r) => r && Object.keys(r).length);
const now = $now.setZone('Asia/Ho_Chi_Minh');
const today = now.toFormat('yyyy-MM-dd');
const nowIso = now.toFormat("yyyy-MM-dd'T'HH:mm:ssZZ"); // e.g. 2026-10-11T21:30:00+07:00
const year = now.year;
const esc = SafeLab.escapeHtml;
const text = (v) => (v === null || v === undefined ? '' : String(v).trim());
const lower = (v) => text(v).toLowerCase();
// Google Sheets treats text starting with = + - @ as a formula: prefix ' so it is stored as plain text.
const sheetRow = (row) => Object.fromEntries(Object.entries(row).map(([k, v]) =>
  [k, typeof v === 'string' && /^[=+\-@]/.test(v) ? "'" + v : v]));
const audit = (actor, action, entity, entityId, details) =>
  sheetRow({ ts: nowIso, actor: actor || 'system', action, entity, entity_id: entityId, details: text(details).slice(0, 1000) });
const link = (url, label) =>
  (text(url) ? `<a href="${esc(url)}">${esc(label)}</a>` : `${esc(label)} (link not configured in CONFIG)`);
const mail = (to, subject, body) => ({
  to: [...new Set([].concat(to).map(lower).filter(Boolean))].join(', '),
  subject: text(subject).replace(/\s+/g, ' '),
  html: `<div style="font-family:Arial,sans-serif;font-size:14px;line-height:1.5;color:#111">${body}` +
    '<p style="color:#6b7280;font-size:12px;margin-top:24px">Automated message from SafeLab (lab-safety approval system).</p></div>',
});
const cfg = SafeLab.configMap(rowsOf('Read CONFIG'));

// ---- 08 Experiment change: F05 row -> CHANGE_PENDING (new F04 needed) or FYI to reviewer ----
const experiments = rowsOf('Read EXPERIMENTS');

const updates = [];
const auditRows = [];
const emails = [];

for (const r of rowsOf('F05 row added')) {
  const submitter = lower(r['Email Address']);
  const expId = text(r['Experiment ID']).toUpperCase();
  const change = text(r['What is changing?']);
  const major = text(r['Does the change add new hazards, chemicals, people or equipment?']).toUpperCase() === 'YES';
  const exp = experiments.find((e) => text(e.exp_id).toUpperCase() === expId);

  if (!exp) {
    emails.push(mail(submitter, `[SafeLab] Experiment not found – ${expId || '(blank ID)'}`,
      `<h2>Experiment ${esc(expId || '(blank ID)')} not found</h2>` +
      '<p>Your Experiment Modification form (F05) refers to an experiment ID that does not exist. ' +
      'Please check the ID (format EXP-YYYY-NNNN) in your approval emails and submit the form again.</p>' +
      `<p>Your change description:<br>${esc(change).replace(/\r?\n/g, '<br>')}</p>`));
    auditRows.push(audit(submitter, 'CHANGE_REJECTED', 'EXPERIMENTS', expId, 'experiment not found'));
    continue;
  }

  const id = text(exp.exp_id);
  const reviewer = lower(exp.reviewer_email) || lower(cfg[SafeLab.reviewerKeyFor(exp.inherent_level)]);
  const changeHtml = `<p><b>What is changing</b> (filed by ${esc(submitter)}):<br>${esc(change).replace(/\r?\n/g, '<br>')}</p>`;
  const summary = SafeLab.experimentSummaryHtml(exp, null, null, { exp_id: id });

  if (major) {
    updates.push({ exp_id: id, status: 'CHANGE_PENDING', current_stage: '', updated_at: nowIso });
    emails.push(mail([reviewer, cfg.PI_EMAIL, exp.leader_email, submitter],
      `[SafeLab] Change requires new approval – ${id} ${text(exp.title)}`,
      `<h2>${esc(id)}: change requires a new safety approval</h2>` +
      '<p>The change adds new hazards, chemicals, people or equipment. The experiment status is now ' +
      `<b>CHANGE_PENDING</b> (was ${esc(exp.status || '-')}). <b>A new F04 Experimental Safety Approval is required</b> ` +
      'before the change is implemented; any pending approval links for this experiment no longer work.</p>' +
      changeHtml + `<p>Submit the new approval here: ${link(cfg.FORM_F04_URL, 'F04 form')}.</p>` + summary));
  } else {
    emails.push(mail(reviewer, `[SafeLab] FYI change – ${id} ${text(exp.title)}`,
      `<h2>${esc(id)}: minor change (for information)</h2>` +
      '<p>The submitter states that the change does <b>not</b> add hazards, chemicals, people or equipment, ' +
      'so no new approval is required. Please contact the experiment leader if you disagree.</p>' + changeHtml + summary));
  }
  auditRows.push(audit(submitter, major ? 'CHANGE_PENDING' : 'CHANGE_FYI', 'EXPERIMENTS', id,
    `${major ? 'adds hazards/chemicals/people/equipment' : 'minor change'}: ${change}`));
}

return [{ json: { experiments: updates, audit: auditRows, emails: emails.filter((e) => e.to) } }];
